(31, 'System', 'System', 4, 'update', NULL, 'products', NULL, NULL, NULL, NULL, NULL, 'App\\Models\\Product', 511, '{\"id\":511,\"product_code\":\"P00457\",\"parent_id\":null,\"product_name\":\"AIDITE | AMM-520 Pro\",\"slug\":\"aidite-amm-520-pro-P00457\",\"product_description\":\"<p>AMM-520 Pro is a wet and dry integrated multi-functional milling machine, with a stable structure and various fixture combinations, meeting different production needs.<\\/p>\",\"key_specifications\":\"<figure class=\\\"table\\\"><table><thead><tr><th><strong>Specification<\\/strong><\\/th><th><strong>Details<\\/strong><\\/th><\\/tr><\\/thead><tbody><tr><td><strong>Number of Axes<\\/strong><\\/td><td>5 axes<\\/td><\\/tr><tr><td><strong>Milling Mode<\\/strong><\\/td><td>Wet and dry<\\/td><\\/tr><tr><td><strong>Processing Type<\\/strong><\\/td><td>Crown\\/bridge, Veneer, Inlay, Custom Abutment, Implant Superstructures (optional CAM module), Implant Bar Clip (optional CAM module), Screw-Retained Bridge (optional CAM module), Complete Denture, Occlusal Splint, Partial Denture Framework<\\/td><\\/tr><tr><td><strong>Millable Material<\\/strong><\\/td><td>Zirconia, PMMA, Glass Ceramic, Premill, PEEK, Titanium Disc, CoCr, Composite Material<\\/td><\\/tr><tr><td><strong>Material Thickness<\\/strong><\\/td><td>10\\u201335\\u202fmm (Disc)<\\/td><\\/tr><tr><td><strong>Accessories<\\/strong><\\/td><td>Work Table, Water Cooler, Water Tank<\\/td><\\/tr><tr><td><strong>Repeat Positioning Accuracy<\\/strong><\\/td><td>\\u00b15\\u202f\\u00b5m<\\/td><\\/tr><tr><td><strong>Linear Drive System<\\/strong><\\/td><td>Linear Guide and Lead Screw<\\/td><\\/tr><tr><td><strong>Rotary Drive System<\\/strong><\\/td><td>Harmonic Reducer<\\/td><\\/tr><tr><td><strong>Clamping System<\\/strong><\\/td><td>Zero-Point Clamping System<\\/td><\\/tr><tr><td><strong>Control System<\\/strong><\\/td><td>Embedded CNC System and AC Bus Servo Motor<\\/td><\\/tr><tr><td><strong>Machine Size<\\/strong><\\/td><td>590 \\u00d7 730 \\u00d7 820\\u202fmm<\\/td><\\/tr><tr><td><strong>Machine Weight<\\/strong><\\/td><td>180\\u202fkg<\\/td><\\/tr><tr><td><strong>Tool Changer<\\/strong><\\/td><td>18 Detachable Modular Design<\\/td><\\/tr><tr><td><strong>Standard Fixture<\\/strong><\\/td><td>Disc Fixture, C-Type Fixture, Block Fixture<\\/td><\\/tr><tr><td><strong>Processing Time<\\/strong><\\/td><td>Single Crown \\u2264 15\\u202fmin, Premill \\u2264 20\\u202fmin, Glass Ceramic \\u2264 20\\u202fmin, Full Denture \\u2264 1.5\\u202fh<\\/td><\\/tr><tr><td><strong>Travel<\\/strong><\\/td><td>XYZ Axis: 180 \\u00d7 110 \\u00d7 100\\u202fmm; A-Axis: \\u00b1361\\u00b0; B-Axis: \\u00b130\\u00b0<\\/td><\\/tr><tr><td><strong>Spindle<\\/strong><\\/td><td>Power: AC 2500\\u202fW; Cooling: Water Cooling; Speed: 60,000\\u202frpm; Chuck Size: \\u03a66\\u202fmm<\\/td><\\/tr><tr><td><strong>Input<\\/strong><\\/td><td>Power Supply: Single-Phase AC 220\\u202fV 50\\/60\\u202fHz; Power: 3\\u202fkW 15\\u202fA; Air Pressure: 6\\u202fBar<\\/td><\\/tr><\\/tbody><\\/table><\\/figure>\",\"packaging\":null,\"warranty\":null,\"category_id\":269,\"delivery_target_days\":\"7\",\"discount\":\"0.00\",\"actual_price\":\"4880000.00\",\"sell_price\":\"4880000.00\",\"available_quantity\":4,\"stock_quantity\":4,\"brand_id\":17,\"product_location\":null,\"has_variations\":0,\"flash_sale\":0,\"weekly_offer\":null,\"special_offer\":null,\"sell_count\":null,\"today_deals\":null,\"main_image\":\"2025-08-05-6891b9e138d36.png\",\"product_catalogue\":null,\"status\":1,\"created_at\":\"2025-08-04T11:30:25.000000Z\",\"updated_at\":\"2025-08-05T08:00:05.000000Z\"}', '{\"id\":511,\"product_code\":\"P00457\",\"parent_id\":null,\"product_name\":\"AIDITE | AMM-520 Pro\",\"slug\":\"aidite-amm-520-pro-P00457\",\"product_description\":\"<p>AMM-520 Pro is a wet and dry integrated multi-functional milling machine, with a stable structure and various fixture combinations, meeting different production needs.<\\/p>\",\"key_specifications\":\"<figure class=\\\"table\\\"